def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = value or ""
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)

        value = value.strip().lower()
        if value.count("@") != 1:
            return ""

        local, domain = value.split("@")
        if domain in {"gmail.com", "googlemail.com"}:
            local = local.split("+", 1)[0].replace(".", "")
            domain = "gmail.com"

        if (
            not local
            or "." not in domain
            or domain.startswith(".")
            or domain.endswith(".")
        ):
            return ""

        return f"{local}@{domain}"

    def normalize_phone(value):
        value = value or ""
        extension = re.search(r"ext|x|#", value, flags=re.IGNORECASE)
        if extension:
            value = value[:extension.start()]

        digits = "".join(character for character in value if character.isdigit())
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]

        if len(digits) != 10 or digits[0] in {"0", "1"}:
            return ""
        return digits

    def normalize_zip(value):
        value = (value or "").strip()

        zip_plus_four = re.fullmatch(r"(\d{5})-\d{4}", value)
        if zip_plus_four:
            value = zip_plus_four.group(1)

        if re.fullmatch(r"\d{4}", value):
            value = "0" + value

        return value if re.fullmatch(r"\d{5}", value) else ""

    def normalize_name(value):
        value = (value or "").strip()
        if value and (value.isupper() or value.islower()):
            return value.title()
        return value

    def parse_updated(value):
        value = value.strip()
        for format_string in (
            "%Y-%m-%dT%H:%M:%S",
            "%Y-%m-%d",
            "%m/%d/%Y",
        ):
            try:
                return datetime.strptime(value, format_string)
            except ValueError:
                pass
        raise ValueError(f"Invalid updated value: {value!r}")

    def is_opted_out(value):
        return (value or "").strip().lower() in {"y", "yes", "true", "1"}

    normalized_rows = []

    for input_index, row in enumerate(rows):
        email = normalize_email(row.get("email", ""))
        phone = normalize_phone(row.get("phone", ""))

        # Rows without either valid contact method do not participate at all.
        if not email and not phone:
            continue

        normalized_rows.append({
            "input_index": input_index,
            "first_name": normalize_name(row.get("first_name", "")),
            "last_name": normalize_name(row.get("last_name", "")),
            "email": email,
            "phone": phone,
            "zip": normalize_zip(row.get("zip", "")),
            "source": (row.get("source", "") or "").strip().lower(),
            "tags": {
                tag.strip().lower()
                for tag in re.split(r"[;,]", row.get("tags", "") or "")
                if tag.strip()
            },
            "opted_out": is_opted_out(row.get("opted_out", "")),
            "updated": parse_updated(row["updated"]),
        })

    # Disjoint-set union handles transitive matches.
    parent = list(range(len(normalized_rows)))

    def find(index):
        while parent[index] != index:
            parent[index] = parent[parent[index]]
            index = parent[index]
        return index

    def union(left, right):
        left_root = find(left)
        right_root = find(right)
        if left_root != right_root:
            parent[right_root] = left_root

    email_owner = {}
    phone_last_name_owner = {}

    for index, row in enumerate(normalized_rows):
        if row["email"]:
            previous = email_owner.get(row["email"])
            if previous is None:
                email_owner[row["email"]] = index
            else:
                union(index, previous)

        if row["phone"] and row["last_name"]:
            key = (row["phone"], row["last_name"].casefold())
            previous = phone_last_name_owner.get(key)
            if previous is None:
                phone_last_name_owner[key] = index
            else:
                union(index, previous)

    groups = {}
    for index, row in enumerate(normalized_rows):
        groups.setdefault(find(index), []).append(row)

    def choose_field(group, field):
        candidates = [row for row in group if row[field]]
        if not candidates:
            return ""

        winner = max(
            candidates,
            key=lambda row: (
                row["source"].casefold() == "manual",
                row["updated"],
                -row["input_index"],
            ),
        )
        return winner[field]

    output = []
    ordered_groups = sorted(
        groups.values(),
        key=lambda group: min(row["input_index"] for row in group),
    )

    for group in ordered_groups:
        all_tags = set()
        for row in group:
            all_tags.update(row["tags"])

        latest_updated = max(row["updated"] for row in group)

        output.append({
            "first_name": choose_field(group, "first_name"),
            "last_name": choose_field(group, "last_name"),
            "zip": choose_field(group, "zip"),
            "email": choose_field(group, "email"),
            "phone": choose_field(group, "phone"),
            "source": choose_field(group, "source"),
            "tags": ";".join(sorted(all_tags)),
            "opted_out": (
                "Y" if any(row["opted_out"] for row in group) else "N"
            ),
            "updated": latest_updated.strftime("%Y-%m-%d"),
        })

    return output
